module.exports = function(RED) {
    const sessionManager = require("./session-manager").getInstance(RED);
    const engine = require("./ivr-engine").getInstance(RED);

    const router = require('express').Router();

    router.post('/ivr/callback', async (req, res) => {
        try {
            const { sessionId, dtmfDigits, callerNumber, eventType, isActive } = req.body;

            console.log(`[Kumva Webhook] Session: ${sessionId} | DTMF: ${dtmfDigits} | Event: ${eventType}`);

            const session = await sessionManager.getSession(sessionId);
            if (!session) {
                console.warn(`Session not found: ${sessionId}`);
                return res.status(200).send('<Response><Hangup/></Response>');
            }

            if (dtmfDigits) {
                RED.events.emit('kumva:resume', {
                    sessionId: sessionId,
                    response: dtmfDigits,
                    nodeId: session.currentNodeId
                });
            }

            // Return basic VoiceXML - will be improved later per node
            res.set('Content-Type', 'text/xml');
            res.send(`<?xml version="1.0" encoding="UTF-8"?>
<Response>
    <Say voice="en-US">Thank you for your response.</Say>
</Response>`);

        } catch (err) {
            console.error("[Webhook Error]", err);
            res.set('Content-Type', 'text/xml');
            res.send('<Response><Hangup/></Response>');
        }
    });

    RED.httpNode.use('/kumva', router);
    console.log("Kumva Webhook ready at /kumva/ivr/callback");
};